import {renderFast,startFast,cleanupFast} from './fast.js';
import {renderExams,renderExam,renderResult,cleanupExam} from './exams.js';
import {scanStats,setScreening,undoScreening,screeningResult,isKnown,readiness,conversationPrompt} from './learning.js';
import * as storage from './storage.js';
import {dayKey,skills,dueTasks,plan,updateProgress} from './scheduler.js';
import {choices,enqueueRetry} from './quiz.js';
import * as audio from './audio.js';
import {journey,settleQuests,claimVisit} from './motivation.js';
const $=s=>document.querySelector(s),app=$('#app'),notice=$('#notice');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cards=[],byId,state=storage.initial(),persistent=true,busy=false,shownOptions=[],pendingImport=null;
document.addEventListener('audio-error',e=>tell(e.detail));
const channel=typeof BroadcastChannel==='function'?new BroadcastChannel('english-stage'):null;
channel?.addEventListener('message',async()=>{if(!busy&&persistent){state=await storage.read();render();}});
function tell(s){notice.textContent=s;}
async function mutate(fn){
 if(busy)return;busy=true;
 const run=async()=>{if(persistent)state=await storage.read();fn(state);settleQuests(state);if(persistent)try{await storage.write(state);channel?.postMessage('saved');}catch{persistent=false;tell('保存できませんでした。この回の記録は一時的です。設定からバックアップしてください。');}};
 try{if(navigator.locks)await navigator.locks.request('english-stage-write',run);else await run();}catch(e){tell(e.message);}finally{busy=false;render();}
}
const skillLabel={read:'読んでわかる',listen:'聞いてわかる',recall:'日本語から英語',self:'自分で思い出す'};
function progress(c){if(isKnown(state,c.id))return '知っている・学習から除外';const p=state.progress[c.id]||{};return skills.every(k=>p[k]?.mastered)?'定着してきた':skills.some(k=>p[k]?.correct)?'思い出せた':state.seen[c.id]?'練習中':'これから';}
function go(hash){location.hash=hash;}
function image(c){return c.image?`<img class="picture" src="${esc(c.image.url)}" alt="${esc(c.ja)}" referrerpolicy="no-referrer"><small class="image-credit">${esc(c.image.credit)}</small>`:visual(c);}
function visual(c){const n=['one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen','twenty'].indexOf(c.en);if(n>=0)return `<div class="visual" aria-label="${n+1}">${n+1}</div>`;const colors={red:'#d76b63',blue:'#779fc5',green:'#729a77',yellow:'#e4c159',white:'#fff',black:'#333'};if(colors[c.en])return `<div class="visual"><span style="width:85px;height:85px;background:${colors[c.en]};border:1px solid #ddd;border-radius:50%"></span></div>`;if(/It's (on|under|in) /.test(c.en)){const pos=c.en.match(/It's (\w+)/)[1];return `<svg role="img" aria-label="${esc(c.ja)}" viewBox="0 0 240 150" width="240" height="150">${pos==='in'?'<rect x="65" y="35" width="110" height="100" rx="8" fill="#d5e1cf" stroke="#526b52" stroke-width="3"/><path d="M90 35V20H150V35" fill="none" stroke="#526b52" stroke-width="3"/>':'<path d="M40 55H200M60 55V135M180 55V135" fill="none" stroke="#526b52" stroke-width="7"/>'}<circle cx="120" cy="${pos==='on'?40:pos==='in'?85:112}" r="12" fill="#db9c48"/></svg>`;}return `<div class="visual" aria-hidden="true">${c.kind==='phrase'?'“ ”':'Aa'}</div>`;}
const audioButtons=(example=true)=>`<div class="audio-controls"><button data-audio="normal">▶ もう一度</button><button data-audio="slow">ゆっくり</button>${example?'<button data-audio="example">例文を聞く</button>':''}<button data-stop>■ 停止</button></div>`;
function cardBody(c){return `<div class="eyebrow">${esc(c.theme)} · ${c.kind==='word'?'WORD':'PHRASE'}</div>${image(c)}<div class="card-en" lang="en-US">${esc(c.en)}</div><div class="card-ja">${esc(c.ja)}</div>${audioButtons()}<div class="example"><p lang="en-US">${esc(c.example)}</p><p>${esc(c.exampleJa)}</p></div><p class="muted">${esc(c.explanation)}</p>`;}
const meter=(value,max,label)=>`<progress class="journey-meter" value="${value}" max="${max}" aria-label="${esc(label)}"></progress>`;
function weekView(j){return `<div class="week-strip" aria-label="最近7日間の学習">${j.week.map(d=>`<div class="week-day ${d.done?'done':''} ${d.today?'is-today':''}"><small>${new Date(d.key+'T12:00:00').toLocaleDateString('ja-JP',{weekday:'short'})}</small><span aria-label="${d.key} ${d.done?'学習済み':'未学習'}">${d.done?'✓':d.today?'・':'−'}</span><small>${d.today?'今日':Number(d.key.slice(-2))+'日'}</small></div>`).join('')}</div>`;}
function questView(j){return `<section class="quest-section"><div class="section-head"><h2>今日のミッション</h2><span class="mini-label">${j.quests.filter(q=>q.value>=q.goal).length} / 3 達成</span></div><div class="quest-list">${j.quests.map(q=>`<div class="quest ${q.value>=q.goal?'complete':''}"><span class="quest-icon" aria-hidden="true">${q.value>=q.goal?'✓':q.icon}</span><div><strong>${q.title}</strong><small>${q.detail}</small>${meter(q.value,q.goal,q.title)}</div><span class="quest-count">${q.value} / ${q.goal}<small>✦ ${q.stars}</small></span></div>`).join('')}</div><small>まちがえても挑戦にカウント。達成すると自動でスター獲得。</small></section>`;}
function badgeView(j){return `<section class="badge-section"><div class="section-head"><h2>がんばりのバッジ</h2><span class="mini-label">${j.badges.filter(b=>b.unlocked).length} / ${j.badges.length}</span></div><div class="badge-grid">${j.badges.map(b=>`<div class="badge ${b.unlocked?'unlocked':''}"><span aria-hidden="true">${b.unlocked?b.icon:'◇'}</span><strong>${b.title}</strong><small>${b.detail}</small><small>${b.unlocked?'獲得！':'これから'}</small></div>`).join('')}</div></section>`;}
const buddy=`<svg class="buddy" viewBox="0 0 160 150" role="img" aria-label="本のともだち"><path d="M24 28Q55 17 80 34Q105 17 136 28V116Q106 105 80 121Q53 105 24 116Z" fill="#fffdf5" stroke="#305c55" stroke-width="4"/><path d="M80 34V121" stroke="#b5cec1" stroke-width="3"/><circle cx="57" cy="65" r="5" fill="#305c55"/><circle cx="105" cy="65" r="5" fill="#305c55"/><path d="M65 82Q80 96 96 82" fill="none" stroke="#305c55" stroke-width="4" stroke-linecap="round"/><ellipse cx="45" cy="79" rx="10" ry="5" fill="#f3c5ac"/><ellipse cx="116" cy="79" rx="10" ry="5" fill="#f3c5ac"/><path d="M13 53L6 46M145 53L154 44M41 129L35 140M118 129L125 140" stroke="#305c55" stroke-width="5" stroke-linecap="round"/><path d="M123 5L126 12L134 14L126 17L123 25L120 17L112 14L120 12Z" fill="#d39b32"/></svg>`;
function home(){
 const j=journey(state),n=scanStats(cards,state),r=readiness(cards,state),f=state.fast;
 app.innerHTML=`<div class="compact-home narrow"><div class="section-head"><div><div class="eyebrow">ENGLISH STAGE</div><h1>さっと確認。</h1></div><a href="#progress" class="pill">Lv. ${j.level} · ${j.xp} XP</a></div><p class="muted">１枚ずつ、わかるものは次へ。</p><section class="panel home-deck"><div class="section-head"><h2>ことばと意味</h2><a href="#library">全${cards.length}項目 →</a></div><button id="start" class="primary start">${f&&f.index<f.ids.length?'カードのつづき':'カードをはじめる'} →</button><div class="home-modes"><button data-quick="read">英語 → 意味</button><button data-quick="recall">意味 → 英語</button><button data-quick="listen">音声 → 意味</button><button data-quick="match">組み合わせ</button></div><div class="home-counts"><span>確認 <strong>${n.checked}/${cards.length}</strong></span><span>わかる <strong>${n.known}</strong></span><span>準備度 <strong>${r.percent}%</strong></span></div><small>準備度は読む・聞くの学習記録に基づく確認範囲です。</small></section><a class="exam-entry" href="#exams"><span><small>すべて選択式 · ３回分</small><strong>英検５級 実戦テスト</strong><span>読む25問 ＋ 聞く25問</span></span><span aria-hidden="true">→</span></a><div class="home-links"><a href="#roadmap">進み具合</a><a href="#conversation">ChatGPTと会話</a><a href="#progress">学習の記録</a></div><details class="panel"><summary>ほかの練習・詳しい見通し</summary>${learningOverview()}<div class="actions"><button id="legacy-study">５問ずつ練習</button><a href="#screen">はじめの仕分け</a><a href="#alphabet">ABCから</a></div></details></div>`;
 $('#start').onclick=async()=>{if(!state.fast||state.fast.index>=state.fast.ids.length)await mutate(s=>startFast(s,cards,'card','new'));go('fast');};
 document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=async()=>{const mode=b.dataset.quick;await mutate(s=>startFast(s,cards,mode,'new'));go('fast');});
 $('#legacy-study').onclick=()=>{if(state.session)go('study');else start('quick');};
}

function learningOverview(){
 const n=scanStats(cards,state),r=readiness(cards,state);
 return `<section class="learning-overview panel"><div class="section-head"><h2>英検5級への道のり</h2><a href="#roadmap">全体の見通し →</a></div><div class="readiness"><strong>${r.percent}<small>%</small></strong><div><b>ことばの準備度</b><small>合格可能性：まだ推定できません</small></div></div>${meter(r.percent,100,'語彙・表現の準備度')}<p class="muted">直近30日で確認した読む・聞くを集計。1回正解は半分、別日2回は75%、定着すると100%の重みです。未確認と自己申告は加点しません。実際の合否には試験形式・時間配分も関わります。</p><div class="learning-links"><a href="#screen"><strong>① はじめのさっとチェック</strong><span>${n.checked} / ${n.total} 確認・知っている ${n.known}こ</span><small>20こずつ。途中で休んでも続きから</small></a><a href="#roadmap"><strong>② 小さなステップで学ぶ</strong><span>1回5問・約2〜3分</span><small>あと何をするか確認しよう</small></a><a href="#conversation"><strong>③ ChatGPTと話してみよう</strong><span>今の力・苦手に合わせて準備</span><small>会話用プロンプトをコピー</small></a></div><details><summary>準備度の見方</summary><p>読む：最近正解 ${r.counts.read} / ${cards.length}、確認した数 ${r.tested.read}。聞く：最近正解 ${r.counts.listen} / ${cards.length}、確認した数 ${r.tested.listen}。日本語から英語・会話力や本番の合格確率はこの数字に含みません。記録が30日を過ぎると再確認のため準備度が下がります。これまでのXPやバッジは残ります。</p><a href="https://www.eiken.or.jp/eiken/exam/grade_5/" target="_blank" rel="noopener">公式の過去問・試験内容で仕上げを確認</a></details></section>`;
}
let scanReveal=false,scanCount=0,scanTarget=null;
function screen(){
 const n=scanStats(cards,state),c=(scanTarget&&cards.find(c=>c.id===scanTarget))||cards.find(c=>!screeningResult(state,c.id));
 if(!c||scanCount>=20){app.innerHTML=`<section class="panel narrow card"><div class="check">✓</div><h1>${!c?'ぜんぶ確認できたよ！':'20こ、確認できたよ！'}</h1><p>全体 ${n.checked} / ${n.total}・知っている ${n.known}こを学習から外しました。</p><p>残り ${n.remaining}こ。自己申告は学習の正解とは別に保存しています。</p><div class="actions"><a href="#home">今日はここまで</a><button class="primary" id="scan-more">${!c?'最初の語から見直す':'次の20こへ'}</button><button id="scan-undo">ひとつ戻す</button></div></section>`;$('#scan-more').onclick=()=>{scanCount=0;scanReveal=false;scanTarget=!c?cards[0].id:null;screen();};$('#scan-undo').onclick=()=>mutate(st=>{scanTarget=undoScreening(st);scanCount=Math.max(0,scanCount-1);scanReveal=false;});return;}
 app.innerHTML=`<div class="narrow"><div class="study-top"><span>はじめのチェック ${n.checked} / ${n.total}</span><a href="#home">休んでホームへ</a></div>${meter(n.checked,n.total,'全体のチェック')}<section class="panel card"><div class="eyebrow">この区切り ${scanCount+1} / 20 · ${esc(c.theme)}</div><h1>意味がすぐ浮かぶかな？</h1><div class="card-en" lang="en-US">${esc(c.en)}</div>${audioButtons(false)}${scanReveal?`<div class="card-ja">${esc(c.ja)}</div><p lang="en-US">${esc(c.example)}</p><p>${esc(c.exampleJa)}</p>`:'<p>まず答えを思い浮かべてみよう。</p><button id="scan-reveal">意味を確かめる</button>'}<div class="scan-actions"><button data-scan="known" class="primary">すぐわかる ✓</button><button data-scan="unsure">ちょっとあやしい</button><button data-scan="unknown">これから覚える</button></div><p class="muted">「すぐわかる」は通常学習から外すよ。読む・聞くの力は別々なので、迷うときは「あやしい」にしよう。</p><div class="actions"><button id="scan-undo" ${state.screening?.undo?.length?'':'disabled'}>ひとつ戻す</button><button id="scan-next">今は飛ばす</button></div></section></div>`;
 bindAudio(c);if($('#scan-reveal'))$('#scan-reveal').onclick=()=>{scanReveal=true;screen();};
 document.querySelectorAll('[data-scan]').forEach(b=>b.onclick=()=>mutate(st=>{setScreening(st,c.id,b.dataset.scan);if(st.session?.tasks.some(t=>t.id===c.id))st.session=null;scanCount++;scanTarget=null;scanReveal=false;if(scanCount===20)celebrate('20こ、確認できたよ！','今日はここまででも大丈夫');}));
 $('#scan-undo').onclick=()=>mutate(st=>{scanTarget=undoScreening(st);scanCount=Math.max(0,scanCount-1);scanReveal=false;});
 $('#scan-next').onclick=()=>{const i=cards.indexOf(c);scanTarget=(cards.slice(i+1).find(x=>!screeningResult(state,x.id))||cards.find(x=>!screeningResult(state,x.id)))?.id;scanReveal=false;screen();};
}
function roadmap(){
 const n=scanStats(cards,state),themes=[...new Set(cards.map(c=>c.theme))];
 app.innerHTML=`<h1>一歩ずつ、英検5級へ。</h1><p>全${cards.filter(c=>c.kind==='word').length}語＋${cards.filter(c=>c.kind==='phrase').length}表現。まず知っているものを確かめ、残りを5問ずつ練習しよう。</p><section class="panel"><h2>次にすること</h2><ol><li>さっとチェック：${n.checked} / ${n.total}確認。<a href="#screen">つづきを確認</a></li><li>あやしい・知らないもの：${n.checked-n.known}こ。知っている${n.known}こは通常学習から除外。</li><li>読む→聞く→日本語から英語、別の日にも確かめよう。</li><li><a href="#conversation">短い会話にチャレンジ</a>。仕上げは<a href="https://www.eiken.or.jp/eiken/exam/grade_5/" target="_blank" rel="noopener">公式過去問</a>で本番の形式を確認。</li></ol><button id="road-start" class="primary">次の5問をはじめる</button></section><div class="road-grid">${themes.map(theme=>{const list=cards.filter(c=>c.theme===theme),known=list.filter(c=>isKnown(state,c.id)).length,checked=list.filter(c=>screeningResult(state,c.id)).length,mastered=list.filter(c=>skills.every(k=>state.progress[c.id]?.[k]?.mastered)).length,read=list.filter(c=>state.progress[c.id]?.read?.lastQuality==='correct').length;return `<section class="panel"><h2>${esc(theme)}</h2>${meter(checked,list.length,theme+'の初回確認')}<p>初回確認 ${checked} / ${list.length}</p><small>知っている ${known} · 読んで正解 ${read} · 3技能で定着 ${mastered}</small><p>5こずつなら約${Math.ceil((list.length-known)/5)}区切り＋復習</p></section>`;}).join('')}</div>`;
 $('#road-start').onclick=()=>state.session?go('study'):start('quick');
}
let conversationTopic='学校と好きなもの',conversationTurns=5;
function conversation(){
 app.innerHTML=`<div class="narrow"><div class="eyebrow">LET'S TALK</div><h1>いまの自分に合う、英語の会話。</h1><p>理解済みのことばと、あやしいことばから会話のお願い文を作るよ。自動送信はせず、下の文をコピーして使います。</p><section class="panel"><label for="talk-topic">話してみたいこと</label><select id="talk-topic">${['学校と好きなもの','食べ物とお買い物','家族と休日','動物と自然','時間と毎日の生活'].map(t=>`<option ${t===conversationTopic?'selected':''}>${t}</option>`).join('')}</select><label for="talk-turns">会話の長さ</label><select id="talk-turns">${[3,5,8].map(n=>`<option value="${n}" ${n===conversationTurns?'selected':''}>${n}往復</option>`).join('')}</select><p class="muted">記録が少ないときは、簡単な質問から様子を確かめる内容になります。</p><label for="talk-prompt">ChatGPTに貼り付ける文</label><textarea id="talk-prompt" rows="16" readonly>${esc(conversationPrompt(cards,state,conversationTopic,conversationTurns))}</textarea><div class="actions"><button class="primary" id="copy-prompt">会話用プロンプトをコピー</button><button id="save-prompt">テキストで保存</button><a href="https://chatgpt.com/" target="_blank" rel="noopener">ChatGPTをひらく ↗</a></div><p id="copy-status" role="status"></p></section><section class="panel"><h2>はじめ方</h2><ol><li>「コピー」を押す。</li><li>保護者と一緒にChatGPTをひらき、新しい音声会話を始める。</li><li>同じチャットにコピーした文を会話の指示として貼り付けて送る。文字を送れない環境では、文を見ながら最初のお願いを話す。</li><li>「わからない」「もう一度」と日本語で言っても大丈夫。</li></ol><p class="muted">デスクトップ版は、最初に音声で新しいチャットを始める必要があります。画面の操作方法は利用環境により異なります。</p><p>会話の結果はアプリの記録に自動で戻りません。終わったらアプリで苦手なことばを確認しよう。</p><a href="https://learn.chatgpt.com/docs/features/voice" target="_blank" rel="noopener">音声会話の使い方（公式）</a></section></div>`;
 $('#talk-topic').onchange=e=>{conversationTopic=e.target.value;conversation();};$('#talk-turns').onchange=e=>{conversationTurns=+e.target.value;conversation();};
 $('#copy-prompt').onclick=async()=>{try{await navigator.clipboard.writeText($('#talk-prompt').value);$('#copy-status').textContent='コピーできました。ChatGPTに貼り付けてください。';}catch{$('#talk-prompt').focus();$('#talk-prompt').select();$('#copy-status').textContent='コピーを許可できませんでした。選択中の文を長押し、またはCtrl+Cでコピーしてください。';}};
 $('#save-prompt').onclick=()=>{const u=URL.createObjectURL(new Blob([$('#talk-prompt').value],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='english-stage-conversation.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
}
function celebrate(title,message){const el=$('#celebration');el.innerHTML=`<strong>${esc(title)}</strong><span>${esc(message)}</span>`;el.classList.add('visible');clearTimeout(celebrate.timer);celebrate.timer=setTimeout(()=>el.classList.remove('visible'),4500);}
async function start(mode){await mutate(s=>{const tasks=plan(cards,s,mode);s.session={id:crypto.randomUUID(),tasks,index:0,tries:{},feedback:null,started:Date.now(),startedXp:journey(s).xp,answered:0,newSeen:0,correct:0,recovered:0,mode};});go('study');}
function sessionDone(s){return s.index>=s.tasks.length||s.answered>=(s.mode==='quick'?5:20)||Date.now()-s.started>=(s.mode==='quick'?180000:600000);}
function study(){
 const s=state.session;if(!s){app.innerHTML='<div class="empty"><h1>今日も、少しずつ。</h1><a href="#home">ホームへ</a></div>';return;}
 if(sessionDone(s)&&!s.feedback){app.innerHTML=`<div class="narrow panel card"><div class="check">✦</div><div class="eyebrow">Nice work today</div><h1>${s.tasks.length?'今日の一歩、できました。':'今は復習するものがありません。'}</h1><div class="session-reward"><span>Lv. ${journey(state).level}</span><strong>+${Math.max(0,journey(state).xp-(s.startedXp??journey(state).xp))} XP</strong><small>今日のミッション ${journey(state).quests.filter(q=>q.value>=q.goal).length} / 3 達成</small></div><p>新しくわかった ${s.newSeen}こ · 自分で正解 ${s.correct}問</p><p>前に苦手だったものを思い出せた ${s.recovered}問</p><p class="muted">残り ${Math.max(0,s.tasks.length-s.index)}ステップ。復習の予定は記録に残ります。</p><div class="actions"><button class="primary" id="finish">今日はここまで</button>${s.index<s.tasks.length?'<button id="continue">もう少しつづける</button>':''}</div></div>`;$('#finish').onclick=()=>mutate(st=>{st.session=null;go('home');});if($('#continue'))$('#continue').onclick=()=>mutate(st=>{st.session.started=Date.now();st.session.answered=0;});return;}
 const task=s.tasks[s.index],c=byId.get(task.id);if(!c){tell('教材が更新されました。ホームから新しい練習を始めてください。');return;}
 let inner='';
 if(task.intro){inner=`${cardBody(c)}<div class="actions"><button class="primary" id="understood">意味と音を確かめた →</button></div><small>ここでは正解の記録はつきません。</small>`;}
 else if(s.feedback){const f=s.feedback;inner=`${f.levelUp?`<div class="level-up">✦ LEVEL UP！ Lv. ${f.levelUp}</div>`:''}<div class="eyebrow">${skillLabel[task.skill]}${f.xp?' · +'+f.xp+' XP':''}</div><div class="feedback ${f.quality==='wrong'?'wrong':''}" role="status"><strong>${f.quality==='correct'?'✓ 思い出せた！':f.quality==='guess'?'確かめて、覚えよう。':'ここで確かめよう。'}</strong><div class="card-en" lang="en-US">${esc(c.en)}</div><p class="card-ja">${esc(c.ja)}</p><p>${esc(c.explanation)}</p><p lang="en-US">${esc(c.example)}</p><small>${esc(c.exampleJa)}</small></div>${audioButtons()}<div class="actions">${f.quality==='correct'?'<button id="guess">たまたま当たった</button>':''}<button class="primary" id="next">次へ →</button></div>`;}
 else{shownOptions=choices(c,cards,task.skill,state.progress[c.id]?.[task.skill]?.attempts||0);inner=`<div class="eyebrow">${skillLabel[task.skill]}</div><h1 style="font-size:25px">${task.skill==='listen'?'英語を聞いて、意味を選ぼう。':task.skill==='recall'?'この意味の英語はどれ？':'この英語の意味はどれ？'}</h1>${task.skill==='listen'?'<div class="visual" aria-hidden="true">♫</div>'+audioButtons(false):`<div class="card-en" ${task.skill==='read'?'lang="en-US"':''}>${esc(task.skill==='recall'?c.ja:c.en)}</div>`}<div class="quiz-options">${shownOptions.map(o=>`<button data-choice="${esc(o.id)}" ${task.skill==='recall'?'lang="en-US"':''}>${esc(o.label)}</button>`).join('')}</div><button id="unknown">わからない・答えを確かめる</button>`;}
 app.innerHTML=`<div class="narrow"><div class="study-top"><span>きょうの練習 · ${s.index+1} / ${s.tasks.length}<small class="study-xp">Lv. ${journey(state).level} · ${journey(state).xp} XP</small></span><button id="pause">中断してホームへ</button></div><div class="progress-line"><span style="width:${100*s.index/Math.max(s.tasks.length,1)}%"></span></div><section class="panel card">${inner}</section><small class="muted">読む・聞く・日本語から英語の記録は別々。復習は翌日以降にも登場します。</small></div>`;
 $('#pause').onclick=()=>go('home');bindAudio(c);
 if(task.skill==='listen'&&!task.intro&&!s.feedback){const b=document.createElement('button');b.textContent='音が出ないとき：読んで練習に切り替える';b.onclick=()=>mutate(st=>{if(st.session?.id===s.id&&st.session.index===s.index)st.session.tasks[st.session.index].skill='read';});app.querySelector('section').append(b);}
 if(task.intro)$('#understood').onclick=()=>mutate(st=>{if(st.session?.id!==s.id||st.session.index!==s.index)return;if(!st.seen[c.id]){st.seen[c.id]=Date.now();st.session.newSeen++;}st.session.index++;});
 else if(s.feedback){$('#next').onclick=()=>next(s);if($('#guess'))$('#guess').onclick=()=>markGuess(s,c,task);}
 else{document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>answer(b.dataset.choice===c.id?'correct':'wrong',s,task));$('#unknown').onclick=()=>answer('wrong',s,task);}
}
function retry(st,task){enqueueRetry(st.session,task);}
async function answer(quality,s,task){audio.stop();await mutate(st=>{
 if(st.session?.id!==s.id||st.session.index!==s.index||st.session.feedback)return;
 const previousJourney=journey(st),now=Date.now(),c=byId.get(task.id),p=st.progress[c.id]||{},old=p[task.skill],key=c.id+':'+task.skill;
 st.session.tries[key]=(st.session.tries[key]||0)+1;st.session.answered++;
 const before=structuredClone(old||null);p[task.skill]=updateProgress(old,quality,now);st.progress[c.id]=p;st.seen[c.id] ||= now;
 const recovered=quality==='correct'&&!!old?.mistakes;
 if(quality==='correct'){st.session.correct++;if(recovered)st.session.recovered++;}else retry(st,task);
 const reward=dayKey(now)+':'+c.id;if(!st.rewards.includes(reward)){st.rewards.push(reward);st.stars++;}
 const event={id:c.id,skill:task.skill,quality,at:now};st.history.push(event);
 const after=journey(st);st.session.feedback={quality,before,at:now,recovered,xp:after.xp-previousJourney.xp,levelUp:after.level>previousJourney.level?after.level:null};

 });}
function markGuess(s,c,task){mutate(st=>{if(st.session?.id!==s.id||st.session.index!==s.index||st.session.feedback?.quality!=='correct')return;const f=st.session.feedback;st.progress[c.id][task.skill]=updateProgress(f.before||{},'guess',f.at);const h=st.history.findLast(h=>h.id===c.id&&h.skill===task.skill&&h.at===f.at);if(h)h.quality='guess';f.quality='guess';st.session.correct--;if(f.recovered)st.session.recovered--;retry(st,task);});}
function next(s){mutate(st=>{if(st.session?.id!==s.id||st.session.index!==s.index||!st.session.feedback)return;st.session.index++;st.session.feedback=null;});}
function bindAudio(c){document.querySelectorAll('[data-audio]').forEach(b=>b.onclick=async()=>{try{await audio.play(c,{example:b.dataset.audio==='example',slow:b.dataset.audio==='slow'});}catch(e){tell(e.message);}});document.querySelectorAll('[data-stop]').forEach(b=>b.onclick=audio.stop);}
function autoAudio(){const s=state.session,t=s?.tasks[s.index];if(location.hash==='#study'&&state.settings.sound&&t&&(t.intro||t.skill==='listen')&&!s.feedback&&!sessionDone(s))audio.play(byId.get(t.id)).catch(e=>tell(e.message));}
function library(learned=false){app.innerHTML=`<div class="eyebrow">YOUR WORD COLLECTION</div><h1>${learned?'できるようになったもの':'ことば帳'}</h1><p class="muted">絵と例文を見て、気になることばを聞いてみよう。</p><div class="search"><input id="search" aria-label="英語や日本語を検索" placeholder="英語・日本語でさがす"><select id="theme" aria-label="テーマ"><option value="">すべてのテーマ</option>${[...new Set(cards.map(c=>c.theme))].map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><p id="count" class="muted"></p><div class="library" id="words"></div>`;const filter=()=>{const q=$('#search').value.trim().toLowerCase(),theme=$('#theme').value,list=cards.filter(c=>(!learned||skills.some(k=>state.progress[c.id]?.[k]?.correct))&&(!theme||c.theme===theme)&&(c.en.toLowerCase().includes(q)||c.ja.includes(q)));$('#count').textContent=list.length+'項目';$('#words').innerHTML=list.map(c=>`<button class="word-item" data-card="${c.id}"><strong lang="en-US">${esc(c.en)}</strong><span>${esc(c.ja)}</span><small>${progress(c)}</small></button>`).join('')||'<p>まだありません。少しずつ練習していこう。</p>';document.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>go('card/'+b.dataset.card));};$('#search').oninput=filter;$('#theme').onchange=filter;filter();}
function detail(id){const c=byId.get(id);if(!c){go('library');return;}app.innerHTML=`<div class="narrow"><a href="#library">← ことば帳</a><section class="panel card">${cardBody(c)}<div class="actions"><button id="known-toggle">${isKnown(state,c.id)?'この語を学習に戻す':'知っているので学習から外す'}</button><button id="self">覚えた、と記録する</button><button id="test-self">絵と答えを隠して思い出す</button></div><small>「覚えた」は自分の申告。自力正解とは別に記録し、翌日また確かめます。</small></section></div>`;bindAudio(c);$('#known-toggle').onclick=()=>mutate(st=>{setScreening(st,id,isKnown(st,id)?'unsure':'known');if(st.session?.tasks.some(t=>t.id===id))st.session=null;tell(isKnown(st,id)?'通常の学習から外しました。いつでも戻せます。':'学習に戻しました。');});$('#self').onclick=()=>mutate(st=>{const now=Date.now();st.seen[id] ||= now;st.progress[id] ||= {};st.progress[id].self=updateProgress(st.progress[id].self,'self',now);st.history.push({id,skill:'self',quality:'self',at:now});tell('自分の申告として記録しました。読む・聞くの練習でも確かめよう。');});$('#test-self').onclick=()=>{app.innerHTML=`<section class="narrow panel card"><h1>${esc(c.ja)}</h1><p>英語を思い出してから、答えを見よう。</p><button id="reveal">答えをみる</button></section>`;$('#reveal').onclick=()=>detail(id);};}
function records(){const j=journey(state);const week=Date.now()-7*86400000,weekly=new Set(state.history.filter(h=>h.at>=week).map(h=>dayKey(h.at))).size;app.innerHTML=`<div class="eyebrow">LEARNING JOURNAL</div><h1>積み重ねが、力になる。</h1>${learningOverview()}<section class="panel"><div class="section-head"><h2>Lv. ${j.level} · 合計 ${j.xp} XP</h2><span>✦ ${state.stars}</span></div>${meter(j.inLevel,100,'レベルの進捗')}<p>次のレベルまで ${j.next} XP · 連続学習 ${j.streak}日</p>${weekView(j)}<p class="muted">1日1回、ことば・技能の組み合わせごとに10 XP。正誤にかかわらず挑戦を記録します。自己申告と訪問ボーナスにはXPはつきません。</p></section>${badgeView(j)}<div class="stats"><div class="stat"><strong>${weekly}</strong><span>この7日間の学習日</span></div><div class="stat"><strong>${Object.keys(state.seen).length}</strong><span>出会ったことば</span></div><div class="stat"><strong>${dueTasks(cards,state).length}</strong><span>復習を待つ問題</span></div></div><section class="panel"><h2>読む力と、聞く力を別々に。</h2><table><thead><tr><th>練習</th><th>自力正解 / 回答</th><th>復習待ち</th></tr></thead><tbody>${skills.map(k=>{const h=state.history.filter(h=>h.skill===k);return `<tr><td>${skillLabel[k]}</td><td>${h.filter(h=>h.quality==='correct').length} / ${h.length}</td><td>${dueTasks(cards,state).filter(t=>t.skill===k).length}</td></tr>`;}).join('')}</tbody></table><p class="muted">「定着してきた」は各技能で別日に3回以上正解し、7日以上空けた確認にも正解したことばです。自分で「覚えた」と申告した記録は正解数に含みません。</p></section><section class="panel"><h2>もう一度確かめたいテーマ</h2>${[...new Set(cards.map(c=>c.theme))].map(t=>{const h=state.history.filter(h=>byId.get(h.id)?.theme===t&&h.quality==='wrong');return h.length?`<p>${esc(t)}：これまでの誤答 ${h.length}問</p>`:'';}).join('')||'<p>練習を始めると、ここに記録されます。</p>'}</section><a href="#settings">バックアップ・学習量の設定 →</a>`;}
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const backup=()=>({app:'english-stage',version:1,createdAt:new Date().toISOString(),state});
function settings(){app.innerHTML=`<div class="narrow"><div class="eyebrow">MAKE IT YOURS</div><h1>自分のペースで。</h1><section class="panel"><div class="settings-row"><label for="new-count">1日の新しいことば<small>復習が多い日は自動で少なくします。</small></label><select id="new-count">${[3,5,10].map(n=>`<option ${n===state.settings.newCount?'selected':''} value="${n}">${n}こ</option>`).join('')}</select></div><div class="settings-row"><label for="auto-sound">カードの音声を自動で流す<small>再生ボタンはいつでも使えます。</small></label><input type="checkbox" id="auto-sound" ${state.settings.sound?'checked':''}></div><div class="settings-row"><label for="motion">動きを減らす</label><input type="checkbox" id="motion" ${!state.settings.motion?'checked':''}></div></section><section class="panel"><h2>記録を大切に保存する</h2><p class="muted">${persistent?'このブラウザの端末内に保存しています。':'一時モードです。ブラウザを閉じる前に書き出してください。'}別の端末への自動同期はありません。</p><div class="actions"><button id="export">バックアップを書き出す</button><label class="tile" for="import">バックアップを選ぶ<input id="import" type="file" accept="application/json,.json"></label></div><div id="import-preview"></div><div id="saved-backup"></div></section><p class="muted">Google Cloud Neural2の米国英語音声です。ふつう・ゆっくりの音声を用意しています。オフライン利用はまだ対応していません。</p></div>`;
 $('#new-count').onchange=e=>{const n=+e.target.value;mutate(s=>{s.settings.newCount=n;});};$('#auto-sound').onchange=e=>{const b=e.target.checked;mutate(s=>{s.settings.sound=b;});};$('#motion').onchange=e=>{const b=!e.target.checked;mutate(s=>{s.settings.motion=b;});};$('#export').onclick=()=>download(backup(),'english-stage-backup.json');
 $('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>10000000)throw Error('10MB以下のファイルを選んでください。');pendingImport=storage.validateBackup(JSON.parse(await f.text()),new Set(cards.map(c=>c.id)));$('#import-preview').innerHTML=`<p>取り込む記録：${Object.keys(pendingImport.seen).length}項目・${pendingImport.history.length}回答。現在の記録を端末内に退避してから置き換えます。</p><button id="restore" class="primary">この記録に復元する</button><button id="cancel-import">やめる</button>`;$('#cancel-import').onclick=()=>{pendingImport=null;$('#import-preview').innerHTML='';};$('#restore').onclick=async()=>{if(!pendingImport)return;const imported=pendingImport;await mutate(s=>{localStorage.setItem('english-stage-before-restore',JSON.stringify({app:'english-stage',version:1,state:s}));Object.assign(s,imported);pendingImport=null;});tell('記録を復元しました。取り込み前の記録は設定から書き出せます。');};}catch(e){tell('読み込めません：'+e.message);}};
 if(localStorage.getItem('english-stage-before-restore')){$('#saved-backup').innerHTML='<button id="old-backup">取り込み前の記録を書き出す</button>';$('#old-backup').onclick=()=>download(JSON.parse(localStorage.getItem('english-stage-before-restore')),'english-stage-before-restore.json');}
}
function alphabet(){app.innerHTML=`<div class="eyebrow">START WITH ABC</div><h1>大文字と小文字は、なかま。</h1><p>大きい A と小さい a は同じ文字。まずは見比べてみよう。</p><div class="library">${[...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'].map(c=>`<div class="panel card" style="margin:0"><div class="card-en" lang="en-US">${c} ${c.toLowerCase()}</div></div>`).join('')}</div><section class="panel"><h2>文字の名前と、単語の中の音</h2><p>A の文字の名前は「エイ」。apple の最初の音とは違います。カタカナだけで覚えず、単語の音声を聞いてみよう。</p><div class="actions"><button data-alpha="g5-w-apple">A · apple を聞く</button><button data-alpha="g5-w-banana">B · banana を聞く</button><button data-alpha="g5-w-cat">C · cat を聞く</button></div></section>`;document.querySelectorAll('[data-alpha]').forEach(b=>b.onclick=()=>audio.play(byId.get(b.dataset.alpha)).catch(e=>tell(e.message)));}
function about(){app.innerHTML=`<div class="narrow panel"><h1>この教材について</h1><p>学校の英語から始める小学5年生向けの独自教材です。現在は基本${cards.filter(c=>c.kind==='word').length}語＋会話・表現${cards.filter(c=>c.kind==='phrase').length}項目。英検の公式教材ではなく、全出題語の網羅や合格を保証するものではありません。</p><p><a href="https://www.eiken.or.jp/eiken/exam/grade_5/" target="_blank" rel="noopener">英検5級の公式案内・過去問</a>で試験形式も確認してください。</p><h2>画像</h2><p>しりとりアプリのAI生成イラストを語義と照合して参照しています。画像は同アプリの配信サーバーから読み込みます。読み込めない場合も英語・訳・例文は使えます。色・数・位置は本アプリの図を使います。</p><h2>音声</h2><p>Google Cloud Text-to-Speechの米国英語音声 en-US-Neural2-F を事前生成しています。単語と例文、それぞれにふつう・ゆっくりの音声があります。合成音声です。スマートフォン実機での再生確認は未完了です。</p><h2>記録と復習</h2><p>IndexedDBに端末内保存。自力正解で1・3・7・14・30・60日後へ。誤答・推測・自己申告は翌日に確認します。誤答は同じ回でも再登場し、1項目・技能につき最大3回です。同じ日に何回も正解しても、復習間隔は伸びません。</p><p>最初のチェックは自己申告で、定着・正解・XPには数えません。「知っている」は通常学習から外し、ことば帳からいつでも戻せます。準備度は直近30日の読む・聞くの確認範囲です。合格確率は実試験による検証がないため算出しません。本人の試用後に量・語義・説明を調整してください。</p></div>`;}
function render(){audio.stop();$('#sound').textContent=state.settings.sound?'音声 ON':'音声 OFF';$('#sound').setAttribute('aria-pressed',state.settings.sound);document.body.classList.toggle('reduce-motion',!state.settings.motion);const route=location.hash.slice(1)||'home';document.body.classList.toggle('studying',['study','screen','fast','exam'].includes(route));document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===route||(a.dataset.nav==='library'&&(route==='learned'||route.startsWith('card/')));if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(route!=='fast')cleanupFast();if(route!=='exam')cleanupExam();const context={app,cards,state,mutate,tell};if(route==='home')home();else if(route==='fast')renderFast(context);else if(route==='exams')renderExams(context);else if(route==='exam')renderExam(context);else if(route.startsWith('exam-result/'))renderResult(context,route.slice(12));else if(route==='study')study();else if(route==='library'||route==='learned')library(route==='learned');else if(route.startsWith('card/'))detail(route.slice(5));else if(route==='progress')records();else if(route==='settings')settings();else if(route==='screen')screen();else if(route==='conversation')conversation();else if(route==='roadmap')roadmap();else if(route==='alphabet')alphabet();else if(route==='about')about();else home();document.querySelectorAll('img.picture').forEach(img=>img.onerror=()=>{img.replaceWith(Object.assign(document.createElement('p'),{textContent:'画像を読み込めません。英語と例文で確かめよう。'}));});autoAudio();}
$('#sound').onclick=()=>mutate(s=>{s.settings.sound=!s.settings.sound;});window.addEventListener('hashchange',()=>{render();app.focus({preventScroll:true});window.scrollTo(0,0);});
try{const response=await fetch('data/grade5.json');if(!response.ok)throw Error('教材の読み込みに失敗しました。再読み込みしてください。');cards=await response.json();byId=new Map(cards.map(c=>[c.id,c]));await audio.init();try{state=await storage.open();}catch{persistent=false;tell('端末に保存できないため一時モードです。設定からバックアップしてください。');}render();}catch(e){tell(e.message);app.innerHTML='<h1>教材を読み込めませんでした</h1><p>通信を確認し、ページを再読み込みしてください。</p>';}

let renderedDay=dayKey(Date.now());
setInterval(()=>{if(dayKey(Date.now())!==renderedDay){renderedDay=dayKey(Date.now());if(!busy)render();}},30000);
document.addEventListener('visibilitychange',async()=>{if(!document.hidden&&!busy&&cards.length){if(persistent)state=await storage.read();render();}});
